import re

# Replace magic numbers/strings with symbolic constants where applicable
# Encapsulate fields via properties
# Use object for job and resume to make code cleaner
# Extract methods for clarity
# Use guard clauses
# Separate query from modifier (search_jobs is a query, post_job is a modifier - already separate)
# Add constructor with encapsulation

class Job:
    def __init__(self, job_title, company, requirements):
        self._job_title = job_title
        self._company = company
        self._requirements = requirements

    @property
    def job_title(self):
        return self._job_title

    @property
    def company(self):
        return self._company

    @property
    def requirements(self):
        return self._requirements

    def matches_criteria(self, criteria):
        criteria_lower = criteria.lower()
        return criteria_lower in self.job_title.lower() or any(criteria_lower in req.lower() for req in self.requirements)

class Resume:
    def __init__(self, name, skills, experience):
        self._name = name
        self._skills = skills
        self._experience = experience

    @property
    def name(self):
        return self._name

    @property
    def skills(self):
        return self._skills

    @property
    def experience(self):
        return self._experience

    def matches_requirements(self, requirements):
        return all(skill in requirements for skill in self.skills)

class JobMarketplace:
    def __init__(self):
        self._job_listings = []
        self._resumes = []

    @property
    def job_listings(self):
        return self._job_listings.copy()

    @property
    def resumes(self):
        return self._resumes.copy()

    def post_job(self, job_title, company, requirements):
        job = Job(job_title, company, requirements)
        self._job_listings.append(job)

    def remove_job(self, job):
        if job not in self._job_listings:
            raise ValueError(f"Job {job.job_title} not found in listings")
        self._job_listings.remove(job)

    def submit_resume(self, name, skills, experience):
        resume = Resume(name, skills, experience)
        self._resumes.append(resume)

    def withdraw_resume(self, resume):
        if resume not in self._resumes:
            raise ValueError(f"Resume for {resume.name} not found")
        self._resumes.remove(resume)

    def search_jobs(self, criteria):
        return [job for job in self._job_listings if job.matches_criteria(criteria)]

    def get_job_applicants(self, job):
        return [resume for resume in self._resumes if resume.matches_requirements(job.requirements)]
